    uint8_t *src2 = av_malloc((unsigned)size +

                              AV_INPUT_BUFFER_PADDING_SIZE);



    if (!src2) {

        av_log(s->avctx, AV_LOG_ERROR,

               "Error allocating temporary buffer\n");

        return AVERROR(ENOMEM);

    }



    if (!s->fill_order) {

        memcpy(src2, src, size);

    } else {

        for (i = 0; i < size; i++)

