                                 uint16_t ipbh0)

{

    CPUS390XState *env = &cpu->env;

    uint32_t sccb;

    uint64_t code;

    int r = 0;



    cpu_synchronize_state(CPU(cpu));

    if (env->psw.mask & PSW_MASK_PSTATE) {

        enter_pgmcheck(cpu, PGM_PRIVILEGED);

        return 0;

    }

    sccb = env->regs[ipbh0 & 0xf];

