static int piix4_device_hotplug(DeviceState *qdev, PCIDevice *dev,

				PCIHotplugState state)

{

    int slot = PCI_SLOT(dev->devfn);

    PIIX4PMState *s = DO_UPCAST(PIIX4PMState, dev,

                                PCI_DEVICE(qdev));



    /* Don't send event when device is enabled during qemu machine creation:

     * it is present on boot, no hotplug event is necessary. We do send an

     * event when the device is disabled later. */

    if (state == PCI_COLDPLUG_ENABLED) {

        return 0;

    }



    s->pci0_status.up = 0;

    s->pci0_status.down = 0;

    if (state == PCI_HOTPLUG_ENABLED) {

        enable_device(s, slot);

    } else {

        disable_device(s, slot);

    }



    pm_update_sci(s);



    return 0;

}

static int parse_inputs(const char **buf, AVFilterInOut **currInputs,

                        AVFilterInOut **openLinks, AVClass *log_ctx)

{

    int pad = 0;



    while(**buf == '[') {

        char *name = parse_link_name(buf, log_ctx);

        AVFilterInOut *match;



        if(!name)

            return -1;



        /* First check if the label is not in the openLinks list */

        match = extract_inout(name, openLinks);



        if(match) {

            /* A label of a open link. Make it one of the inputs of the next

               filter */

            if(match->type != LinkTypeOut) {

                av_log(log_ctx, AV_LOG_ERROR,

                       "Label \"%s\" appears twice as input!\n", match->name);

                return -1;

            }


        } else {

            /* Not in the list, so add it as an input */

            match = av_mallocz(sizeof(AVFilterInOut));

            match->name    = name;

            match->type    = LinkTypeIn;

            match->pad_idx = pad;

        }



        insert_inout(currInputs, match);



        *buf += consume_whitespace(*buf);

        pad++;

    }



    return pad;

}

static int decode_exponents(AC3DecodeContext *ctx)

{

    ac3_audio_block *ab = &ctx->audio_block;

    int i;

    uint8_t *exps;

    uint8_t *dexps;



    if (ab->flags & AC3_AB_CPLINU && ab->cplexpstr != AC3_EXPSTR_REUSE)

        if (_decode_exponents(ab->cplexpstr, ab->ncplgrps, ab->cplabsexp,

                    ab->cplexps, ab->dcplexps + ab->cplstrtmant))

            return -1;

    for (i = 0; i < ctx->bsi.nfchans; i++)

        if (ab->chexpstr[i] != AC3_EXPSTR_REUSE) {

            exps = ab->exps[i];

            dexps = ab->dexps[i];

            if (_decode_exponents(ab->chexpstr[i], ab->nchgrps[i], exps[0], exps + 1, dexps + 1))

                return -1;

        }

    if (ctx->bsi.flags & AC3_BSI_LFEON && ab->lfeexpstr != AC3_EXPSTR_REUSE)

        if (_decode_exponents(ab->lfeexpstr, 2, ab->lfeexps[0], ab->lfeexps + 1, ab->dlfeexps))

            return -1;

    return 0;

}

static void mxf_write_multi_descriptor(AVFormatContext *s)

{

    MXFContext *mxf = s->priv_data;

    AVIOContext *pb = s->pb;

    const uint8_t *ul;

    int i;



    mxf_write_metadata_key(pb, 0x014400);

    PRINT_KEY(s, "multiple descriptor key", pb->buf_ptr - 16);

    klv_encode_ber_length(pb, 64 + 16 * s->nb_streams);



    mxf_write_local_tag(pb, 16, 0x3C0A);

    mxf_write_uuid(pb, MultipleDescriptor, 0);

    PRINT_KEY(s, "multi_desc uid", pb->buf_ptr - 16);



    // write sample rate

    mxf_write_local_tag(pb, 8, 0x3001);

    avio_wb32(pb, mxf->time_base.den);

    avio_wb32(pb, mxf->time_base.num);



    // write essence container ul

    mxf_write_local_tag(pb, 16, 0x3004);

    if (mxf->essence_container_count > 1)

        ul = multiple_desc_ul;

    else {

        MXFStreamContext *sc = s->streams[0]->priv_data;

        ul = mxf_essence_container_uls[sc->index].container_ul;

    }

    avio_write(pb, ul, 16);



    // write sub descriptor refs

    mxf_write_local_tag(pb, s->nb_streams * 16 + 8, 0x3F01);

    mxf_write_refs_count(pb, s->nb_streams);

    for (i = 0; i < s->nb_streams; i++)

        mxf_write_uuid(pb, SubDescriptor, i);

}

