int ff_v4l2_m2m_codec_init(AVCodecContext *avctx)

{

    int ret = AVERROR(EINVAL);

    struct dirent *entry;

    char node[PATH_MAX];

    DIR *dirp;



    V4L2m2mContext *s = avctx->priv_data;

    s->avctx = avctx;



    dirp = opendir("/dev");

    if (!dirp)

        return AVERROR(errno);



    for (entry = readdir(dirp); entry; entry = readdir(dirp)) {



        if (strncmp(entry->d_name, "video", 5))

            continue;



        snprintf(node, sizeof(node), "/dev/%s", entry->d_name);

        av_log(s->avctx, AV_LOG_DEBUG, "probing device %s\n", node);

        strncpy(s->devname, node, strlen(node) + 1);

        ret = v4l2_probe_driver(s);

        if (!ret)

                break;

    }



    closedir(dirp);



    if (ret) {

        av_log(s->avctx, AV_LOG_ERROR, "Could not find a valid device\n");

        memset(s->devname, 0, sizeof(s->devname));



        return ret;

    }



    av_log(s->avctx, AV_LOG_INFO, "Using device %s\n", node);



    return v4l2_configure_contexts(s);

}

static int read_key(void)

{

#if HAVE_TERMIOS_H

    int n = 1;

    unsigned char ch;

    struct timeval tv;

    fd_set rfds;



    FD_ZERO(&rfds);

    FD_SET(0, &rfds);

    tv.tv_sec = 0;

    tv.tv_usec = 0;

    n = select(1, &rfds, NULL, NULL, &tv);

    if (n > 0) {

        n = read(0, &ch, 1);

        if (n == 1)

            return ch;



        return n;

    }

#elif HAVE_CONIO_H

    if(kbhit())

        return(getch());

#endif

    return -1;

}

