                                       target_phys_addr_t addr,

                                       unsigned size)

{

    if (!mr->ops->valid.unaligned && (addr & (size - 1))) {

        return false;

    }



    /* Treat zero as compatibility all valid */

    if (!mr->ops->valid.max_access_size) {

        return true;

