static int blk_root_inactivate(BdrvChild *child)

{

    BlockBackend *blk = child->opaque;



    if (blk->disable_perm) {

        return 0;

    }



    /* Only inactivate BlockBackends for guest devices (which are inactive at

     * this point because the VM is stopped) and unattached monitor-owned

     * BlockBackends. If there is still any other user like a block job, then

     * we simply can't inactivate the image. */

    if (!blk->dev && !blk->name[0]) {

        return -EPERM;

    }



    blk->disable_perm = true;

    if (blk->root) {

        bdrv_child_try_set_perm(blk->root, 0, BLK_PERM_ALL, &error_abort);

    }



    return 0;

}

void sigaction_invoke(struct sigaction *action,

                      struct qemu_signalfd_siginfo *info)

{

    siginfo_t si = { 0 };

    si.si_signo = info->ssi_signo;

    si.si_errno = info->ssi_errno;

    si.si_code = info->ssi_code;



    /* Convert the minimal set of fields defined by POSIX.

     * Positive si_code values are reserved for kernel-generated

     * signals, where the valid siginfo fields are determined by

     * the signal number.  But according to POSIX, it is unspecified

     * whether SI_USER and SI_QUEUE have values less than or equal to

     * zero.

     */

    if (info->ssi_code == SI_USER || info->ssi_code == SI_QUEUE ||

        info->ssi_code <= 0) {

        /* SIGTERM, etc.  */

        si.si_pid = info->ssi_pid;

        si.si_uid = info->ssi_uid;

    } else if (info->ssi_signo == SIGILL || info->ssi_signo == SIGFPE ||

               info->ssi_signo == SIGSEGV || info->ssi_signo == SIGBUS) {

        si.si_addr = (void *)(uintptr_t)info->ssi_addr;

    } else if (info->ssi_signo == SIGCHLD) {

        si.si_pid = info->ssi_pid;

        si.si_status = info->ssi_status;

        si.si_uid = info->ssi_uid;

    }

    action->sa_sigaction(info->ssi_signo, &si, NULL);

}

static void start_frame(AVFilterLink *inlink, AVFilterBufferRef *picref)

{

    PixdescTestContext *priv = inlink->dst->priv;

    AVFilterLink *outlink    = inlink->dst->outputs[0];

    AVFilterBufferRef *outpicref;

    int i;



    outlink->out_buf = avfilter_get_video_buffer(outlink, AV_PERM_WRITE,

                                                outlink->w, outlink->h);

    outpicref = outlink->out_buf;

    avfilter_copy_buffer_ref_props(outpicref, picref);



    for (i = 0; i < 4; i++) {

        int h = outlink->h;

        h = i == 1 || i == 2 ? h>>priv->pix_desc->log2_chroma_h : h;

        if (outpicref->data[i]) {

            uint8_t *data = outpicref->data[i] +

                (outpicref->linesize[i] > 0 ? 0 : outpicref->linesize[i] * (h-1));

            memset(data, 0, FFABS(outpicref->linesize[i]) * h);

        }

    }



    /* copy palette */

    if (priv->pix_desc->flags & PIX_FMT_PAL)

        memcpy(outpicref->data[1], outpicref->data[1], 256*4);



    avfilter_start_frame(outlink, avfilter_ref_buffer(outpicref, ~0));

}

static void decode_profile_tier_level(GetBitContext *gb, AVCodecContext *avctx,

                                      PTLCommon *ptl)

{

    int i;



    ptl->profile_space = get_bits(gb, 2);

    ptl->tier_flag     = get_bits1(gb);

    ptl->profile_idc   = get_bits(gb, 5);

    if (ptl->profile_idc == FF_PROFILE_HEVC_MAIN)

        av_log(avctx, AV_LOG_DEBUG, "Main profile bitstream\n");

    else if (ptl->profile_idc == FF_PROFILE_HEVC_MAIN_10)

        av_log(avctx, AV_LOG_DEBUG, "Main 10 profile bitstream\n");

    else if (ptl->profile_idc == FF_PROFILE_HEVC_MAIN_STILL_PICTURE)

        av_log(avctx, AV_LOG_DEBUG, "Main Still Picture profile bitstream\n");

    else

        av_log(avctx, AV_LOG_WARNING, "Unknown HEVC profile: %d\n", ptl->profile_idc);



    for (i = 0; i < 32; i++)

        ptl->profile_compatibility_flag[i] = get_bits1(gb);

    ptl->progressive_source_flag    = get_bits1(gb);

    ptl->interlaced_source_flag     = get_bits1(gb);

    ptl->non_packed_constraint_flag = get_bits1(gb);

    ptl->frame_only_constraint_flag = get_bits1(gb);



    skip_bits(gb, 16); // XXX_reserved_zero_44bits[0..15]

    skip_bits(gb, 16); // XXX_reserved_zero_44bits[16..31]

    skip_bits(gb, 12); // XXX_reserved_zero_44bits[32..43]

}

