static int pvf_read_header(AVFormatContext *s)

{

    char buffer[32];

    AVStream *st;

    int bps, channels, sample_rate;



    avio_skip(s->pb, 5);

    ff_get_line(s->pb, buffer, sizeof(buffer));

    if (sscanf(buffer, "%d %d %d",

               &channels,

               &sample_rate,

               &bps) != 3)

        return AVERROR_INVALIDDATA;



    if (channels <= 0 || bps <= 0 || sample_rate <= 0)

        return AVERROR_INVALIDDATA;



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    st->codecpar->codec_type  = AVMEDIA_TYPE_AUDIO;

    st->codecpar->channels    = channels;

    st->codecpar->sample_rate = sample_rate;

    st->codecpar->codec_id    = ff_get_pcm_codec_id(bps, 0, 1, 0xFFFF);

    st->codecpar->bits_per_coded_sample = bps;

    st->codecpar->block_align = bps * st->codecpar->channels / 8;



    avpriv_set_pts_info(st, 64, 1, st->codecpar->sample_rate);



    return 0;

}

void helper_msa_st_df(CPUMIPSState *env, uint32_t df, uint32_t wd, uint32_t rs,

                     int32_t s10)

{

    wr_t *pwd = &(env->active_fpu.fpr[wd].wr);

    target_ulong addr = env->active_tc.gpr[rs] + (s10 << df);

    int i;



    switch (df) {

    case DF_BYTE:

        for (i = 0; i < DF_ELEMENTS(DF_BYTE); i++) {

            do_sb(env, addr + (i << DF_BYTE), pwd->b[i],

                    env->hflags & MIPS_HFLAG_KSU);

        }

        break;

    case DF_HALF:

        for (i = 0; i < DF_ELEMENTS(DF_HALF); i++) {

            do_sh(env, addr + (i << DF_HALF), pwd->h[i],

                    env->hflags & MIPS_HFLAG_KSU);

        }

        break;

    case DF_WORD:

        for (i = 0; i < DF_ELEMENTS(DF_WORD); i++) {

            do_sw(env, addr + (i << DF_WORD), pwd->w[i],

                    env->hflags & MIPS_HFLAG_KSU);

        }

        break;

    case DF_DOUBLE:

        for (i = 0; i < DF_ELEMENTS(DF_DOUBLE); i++) {

            do_sd(env, addr + (i << DF_DOUBLE), pwd->d[i],

                    env->hflags & MIPS_HFLAG_KSU);

        }

        break;

    }

}

