static void pfpu_start(MilkymistPFPUState *s)

{

    int x, y;

    int i;



    for (y = 0; y <= s->regs[R_VMESHLAST]; y++) {

        for (x = 0; x <= s->regs[R_HMESHLAST]; x++) {

            D_EXEC(qemu_log("\nprocessing x=%d y=%d\n", x, y));



            /* set current position */

            s->gp_regs[GPR_X] = x;

            s->gp_regs[GPR_Y] = y;



            /* run microcode on this position */

            i = 0;

            while (pfpu_decode_insn(s)) {

                /* decode at most MICROCODE_WORDS instructions */

                if (i++ >= MICROCODE_WORDS) {

                    error_report("milkymist_pfpu: too many instructions "

                            "executed in microcode. No VECTOUT?");

                    break;

                }

            }



            /* reset pc for next run */

            s->regs[R_PC] = 0;

        }

    }



    s->regs[R_VERTICES] = x * y;



    trace_milkymist_pfpu_pulse_irq();

    qemu_irq_pulse(s->irq);

}

static ssize_t usbnet_receive(VLANClientState *nc, const uint8_t *buf, size_t size)

{

    USBNetState *s = DO_UPCAST(NICState, nc, nc)->opaque;

    struct rndis_packet_msg_type *msg;



    if (is_rndis(s)) {

        msg = (struct rndis_packet_msg_type *) s->in_buf;

        if (!s->rndis_state == RNDIS_DATA_INITIALIZED)

            return -1;

        if (size + sizeof(struct rndis_packet_msg_type) > sizeof(s->in_buf))

            return -1;



        memset(msg, 0, sizeof(struct rndis_packet_msg_type));

        msg->MessageType = cpu_to_le32(RNDIS_PACKET_MSG);

        msg->MessageLength = cpu_to_le32(size + sizeof(struct rndis_packet_msg_type));

        msg->DataOffset = cpu_to_le32(sizeof(struct rndis_packet_msg_type) - 8);

        msg->DataLength = cpu_to_le32(size);

        /* msg->OOBDataOffset;

         * msg->OOBDataLength;

         * msg->NumOOBDataElements;

         * msg->PerPacketInfoOffset;

         * msg->PerPacketInfoLength;

         * msg->VcHandle;

         * msg->Reserved;

         */

        memcpy(msg + 1, buf, size);

        s->in_len = size + sizeof(struct rndis_packet_msg_type);

    } else {

        if (size > sizeof(s->in_buf))

            return -1;

        memcpy(s->in_buf, buf, size);

        s->in_len = size;

    }

    s->in_ptr = 0;

    return size;

}

static void libschroedinger_flush(AVCodecContext *avctx)

{

    /* Got a seek request. Free the decoded frames queue and then reset

     * the decoder */

    SchroDecoderParams *p_schro_params = avctx->priv_data;



    /* Free data in the output frame queue. */

    ff_schro_queue_free(&p_schro_params->dec_frame_queue,

                        libschroedinger_decode_frame_free);



    ff_schro_queue_init(&p_schro_params->dec_frame_queue);

    schro_decoder_reset(p_schro_params->decoder);

    p_schro_params->eos_pulled = 0;

    p_schro_params->eos_signalled = 0;

}

static void vmsa_ttbcr_raw_write(CPUARMState *env, const ARMCPRegInfo *ri,

                                 uint64_t value)

{

    int maskshift = extract32(value, 0, 3);



    if (arm_feature(env, ARM_FEATURE_LPAE) && (value & (1 << 31))) {

        value &= ~((7 << 19) | (3 << 14) | (0xf << 3));

    } else {

        value &= 7;

    }

    /* Note that we always calculate c2_mask and c2_base_mask, but

     * they are only used for short-descriptor tables (ie if EAE is 0);

     * for long-descriptor tables the TTBCR fields are used differently

     * and the c2_mask and c2_base_mask values are meaningless.

     */

    env->cp15.c2_control = value;

    env->cp15.c2_mask = ~(((uint32_t)0xffffffffu) >> maskshift);

    env->cp15.c2_base_mask = ~((uint32_t)0x3fffu >> maskshift);

}

static void pci_update_mappings(PCIDevice *d)

{

    PCIIORegion *r;

    int i;

    pcibus_t new_addr;



    for(i = 0; i < PCI_NUM_REGIONS; i++) {

        r = &d->io_regions[i];



        /* this region isn't registered */

        if (!r->size)

            continue;



        new_addr = pci_bar_address(d, i, r->type, r->size);



        /* This bar isn't changed */

        if (new_addr == r->addr)

            continue;



        /* now do the real mapping */

        if (r->addr != PCI_BAR_UNMAPPED) {

            trace_pci_update_mappings_del(d, pci_bus_num(d->bus),

                                          PCI_SLOT(d->devfn),

                                          PCI_FUNC(d->devfn),

                                          i, r->addr, r->size);

            memory_region_del_subregion(r->address_space, r->memory);

        }

        r->addr = new_addr;

        if (r->addr != PCI_BAR_UNMAPPED) {

            trace_pci_update_mappings_add(d, pci_bus_num(d->bus),

                                          PCI_SLOT(d->devfn),

                                          PCI_FUNC(d->devfn),

                                          i, r->addr, r->size);

            memory_region_add_subregion_overlap(r->address_space,

                                                r->addr, r->memory, 1);

        }

    }



    pci_update_vga(d);

}

