static void disas_pc_rel_adr(DisasContext *s, uint32_t insn)

{

    unsigned int page, rd;

    uint64_t base;

    int64_t offset;



    page = extract32(insn, 31, 1);

    /* SignExtend(immhi:immlo) -> offset */

    offset = ((int64_t)sextract32(insn, 5, 19) << 2) | extract32(insn, 29, 2);

    rd = extract32(insn, 0, 5);

    base = s->pc - 4;



    if (page) {

        /* ADRP (page based) */

        base &= ~0xfff;

        offset <<= 12;

    }



    tcg_gen_movi_i64(cpu_reg(s, rd), base + offset);

}

static int vp56_size_changed(VP56Context *s)
{
    AVCodecContext *avctx = s->avctx;
    int stride = s->frames[VP56_FRAME_CURRENT]->linesize[0];
    int i;
    s->plane_width[0]  = s->plane_width[3]  = avctx->coded_width;
    s->plane_width[1]  = s->plane_width[2]  = avctx->coded_width/2;
    s->plane_height[0] = s->plane_height[3] = avctx->coded_height;
    s->plane_height[1] = s->plane_height[2] = avctx->coded_height/2;
    for (i=0; i<4; i++)
        s->stride[i] = s->flip * s->frames[VP56_FRAME_CURRENT]->linesize[i];
    s->mb_width  = (avctx->coded_width +15) / 16;
    s->mb_height = (avctx->coded_height+15) / 16;
    if (s->mb_width > 1000 || s->mb_height > 1000) {
        ff_set_dimensions(avctx, 0, 0);
        av_log(avctx, AV_LOG_ERROR, "picture too big\n");
        return AVERROR_INVALIDDATA;
    }
    av_reallocp_array(&s->above_blocks, 4*s->mb_width+6,
                      sizeof(*s->above_blocks));
    av_reallocp_array(&s->macroblocks, s->mb_width*s->mb_height,
                      sizeof(*s->macroblocks));
    av_free(s->edge_emu_buffer_alloc);
    s->edge_emu_buffer_alloc = av_malloc(16*stride);
    s->edge_emu_buffer = s->edge_emu_buffer_alloc;
    if (!s->above_blocks || !s->macroblocks || !s->edge_emu_buffer_alloc)
        return AVERROR(ENOMEM);
    if (s->flip < 0)
        s->edge_emu_buffer += 15 * stride;
    if (s->alpha_context)
        return vp56_size_changed(s->alpha_context);
    return 0;
}

static void framebuffer_update_request(VncState *vs, int incremental,

				       int x_position, int y_position,

				       int w, int h)

{

    if (x_position > ds_get_width(vs->ds))

        x_position = ds_get_width(vs->ds);

    if (y_position > ds_get_height(vs->ds))

        y_position = ds_get_height(vs->ds);

    if (x_position + w >= ds_get_width(vs->ds))

        w = ds_get_width(vs->ds)  - x_position;

    if (y_position + h >= ds_get_height(vs->ds))

        h = ds_get_height(vs->ds) - y_position;



    int i;

    vs->need_update = 1;

    if (!incremental) {

	char *old_row = vs->old_data + y_position * ds_get_linesize(vs->ds);



	for (i = 0; i < h; i++) {

            vnc_set_bits(vs->dirty_row[y_position + i],

                         (ds_get_width(vs->ds) / 16), VNC_DIRTY_WORDS);

	    memset(old_row, 42, ds_get_width(vs->ds) * vs->depth);

	    old_row += ds_get_linesize(vs->ds);

	}

    }

}

static int add_metadata_from_side_data(AVCodecContext *avctx, AVFrame *frame)

{

    int size, ret = 0;

    const uint8_t *side_metadata;

    const uint8_t *end;



    side_metadata = av_packet_get_side_data(avctx->pkt,

                                            AV_PKT_DATA_STRINGS_METADATA, &size);

    if (!side_metadata)

        goto end;

    end = side_metadata + size;

    while (side_metadata < end) {

        const uint8_t *key = side_metadata;

        const uint8_t *val = side_metadata + strlen(key) + 1;

        int ret = av_dict_set(avpriv_frame_get_metadatap(frame), key, val, 0);

        if (ret < 0)

            break;

        side_metadata = val + strlen(val) + 1;

    }

end:

    return ret;

}

