void init_get_bits(GetBitContext *s,

                   UINT8 *buffer, int buffer_size)

{

    s->buffer= buffer;

    s->size= buffer_size;

    s->buffer_end= buffer + buffer_size;

#ifdef ALT_BITSTREAM_READER

    s->index=0;

#elif defined LIBMPEG2_BITSTREAM_READER

    s->buffer_ptr = buffer;

    s->bit_count = 16;

    s->cache = 0;

#elif defined A32_BITSTREAM_READER

    s->buffer_ptr = (uint32_t*)buffer;

    s->bit_count = 32;

    s->cache0 = 0;

    s->cache1 = 0;

#endif

    {

        OPEN_READER(re, s)

        UPDATE_CACHE(re, s)

//        UPDATE_CACHE(re, s)

        CLOSE_READER(re, s)

    }

#ifdef A32_BITSTREAM_READER

    s->cache1 = 0;

#endif

}

static void seek_to_maindata(MPADecodeContext *s, long backstep)

{

    UINT8 *ptr;



    /* compute current position in stream */

    ptr = s->gb.buffer + (get_bits_count(&s->gb)>>3);



    /* copy old data before current one */

    ptr -= backstep;

    memcpy(ptr, s->inbuf1[s->inbuf_index ^ 1] + 

           BACKSTEP_SIZE + s->old_frame_size - backstep, backstep);

    /* init get bits again */

    init_get_bits(&s->gb, ptr, s->frame_size + backstep);



    /* prepare next buffer */

    s->inbuf_index ^= 1;

    s->inbuf = &s->inbuf1[s->inbuf_index][BACKSTEP_SIZE];

    s->old_frame_size = s->frame_size;

}

static void mmubooke_create_initial_mapping(CPUPPCState *env)

{

    struct boot_info *bi = env->load_info;

    ppcmas_tlb_t *tlb = booke206_get_tlbm(env, 1, 0, 0);

    hwaddr size, dt_end;

    int ps;



    /* Our initial TLB entry needs to cover everything from 0 to

       the device tree top */

    dt_end = bi->dt_base + bi->dt_size;

    ps = booke206_page_size_to_tlb(dt_end) + 1;

    if (ps & 1) {

        /* e500v2 can only do even TLB size bits */

        ps++;

    }

    size = (ps << MAS1_TSIZE_SHIFT);

    tlb->mas1 = MAS1_VALID | size;

    tlb->mas2 = 0;

    tlb->mas7_3 = 0;

    tlb->mas7_3 |= MAS3_UR | MAS3_UW | MAS3_UX | MAS3_SR | MAS3_SW | MAS3_SX;



    env->tlb_dirty = true;

}

static int ds1225y_set_to_mode(ds1225y_t *NVRAM, nvram_open_mode mode, const char *filemode)

