static void move_audio(vorbis_enc_context *venc, float **audio, int *samples, int sf_size)

{

    AVFrame *cur = NULL;

    int frame_size = 1 << (venc->log2_blocksize[1] - 1);

    int subframes = frame_size / sf_size;



    for (int sf = 0; sf < subframes; sf++) {

        cur = ff_bufqueue_get(&venc->bufqueue);

        *samples += cur->nb_samples;



        for (int ch = 0; ch < venc->channels; ch++) {

            const float *input = (float *) cur->extended_data[ch];

            const size_t len  = cur->nb_samples * sizeof(float);

            memcpy(&audio[ch][sf*sf_size], input, len);

        }

        av_frame_free(&cur);

    }

}

static int spapr_set_associativity(void *fdt, sPAPREnvironment *spapr)

{

    int ret = 0, offset;

    CPUPPCState *env;

    char cpu_model[32];

    int smt = kvmppc_smt_threads();



    assert(spapr->cpu_model);



    for (env = first_cpu; env != NULL; env = env->next_cpu) {

        uint32_t associativity[] = {cpu_to_be32(0x5),

                                    cpu_to_be32(0x0),

                                    cpu_to_be32(0x0),

                                    cpu_to_be32(0x0),

                                    cpu_to_be32(env->numa_node),

                                    cpu_to_be32(env->cpu_index)};



        if ((env->cpu_index % smt) != 0) {

            continue;

        }



        snprintf(cpu_model, 32, "/cpus/%s@%x", spapr->cpu_model,

                 env->cpu_index);



        offset = fdt_path_offset(fdt, cpu_model);

        if (offset < 0) {

            return offset;

        }



        ret = fdt_setprop(fdt, offset, "ibm,associativity", associativity,

                          sizeof(associativity));

        if (ret < 0) {

            return ret;

        }

    }

    return ret;

}

static int get_best_header(FLACParseContext* fpc, const uint8_t **poutbuf,

                           int *poutbuf_size)

{

    FLACHeaderMarker *header = fpc->best_header;

    FLACHeaderMarker *child  = header->best_child;

    if (!child) {

        *poutbuf_size = av_fifo_size(fpc->fifo_buf) - header->offset;

    } else {

        *poutbuf_size = child->offset - header->offset;



        /* If the child has suspicious changes, log them */

        check_header_mismatch(fpc, header, child, 0);

    }



    if (header->fi.channels != fpc->avctx->channels ||

        (!fpc->avctx->channel_layout && header->fi.channels <= 6)) {

        fpc->avctx->channels = header->fi.channels;

        ff_flac_set_channel_layout(fpc->avctx);

    }

    fpc->avctx->sample_rate = header->fi.samplerate;

    fpc->pc->duration       = header->fi.blocksize;

    *poutbuf = flac_fifo_read_wrap(fpc, header->offset, *poutbuf_size,

                                        &fpc->wrap_buf,

                                        &fpc->wrap_buf_allocated_size);



    fpc->best_header_valid = 0;

    /* Return the negative overread index so the client can compute pos.

       This should be the amount overread to the beginning of the child */

    if (child)

        return child->offset - av_fifo_size(fpc->fifo_buf);

    return 0;

}

static int disas_cp14_write(CPUState * env, DisasContext *s, uint32_t insn)

{

    int crn = (insn >> 16) & 0xf;

    int crm = insn & 0xf;

    int op1 = (insn >> 21) & 7;

    int op2 = (insn >> 5) & 7;

    int rt = (insn >> 12) & 0xf;

    TCGv tmp;



    if (arm_feature(env, ARM_FEATURE_THUMB2EE)) {

        if (op1 == 6 && crn == 0 && crm == 0 && op2 == 0) {

            /* TEECR */

            if (IS_USER(s))

                return 1;

            tmp = load_reg(s, rt);

            gen_helper_set_teecr(cpu_env, tmp);

            dead_tmp(tmp);

            return 0;

        }

        if (op1 == 6 && crn == 1 && crm == 0 && op2 == 0) {

            /* TEEHBR */

            if (IS_USER(s) && (env->teecr & 1))

                return 1;

            tmp = load_reg(s, rt);

            store_cpu_field(tmp, teehbr);

            return 0;

        }

    }

    fprintf(stderr, "Unknown cp14 write op1:%d crn:%d crm:%d op2:%d\n",

            op1, crn, crm, op2);

    return 1;

}

static void v9fs_stat(void *opaque)

{

    int32_t fid;

    V9fsStat v9stat;

    ssize_t err = 0;

    size_t offset = 7;

    struct stat stbuf;

    V9fsFidState *fidp;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    pdu_unmarshal(pdu, offset, "d", &fid);




    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }

    err = v9fs_co_lstat(pdu, &fidp->path, &stbuf);

    if (err < 0) {

        goto out;

    }

    err = stat_to_v9stat(pdu, &fidp->path, &stbuf, &v9stat);

    if (err < 0) {

        goto out;

    }

    offset += pdu_marshal(pdu, offset, "wS", 0, &v9stat);

    err = offset;

    v9fs_stat_free(&v9stat);

out:

    put_fid(pdu, fidp);

out_nofid:

    trace_v9fs_stat_return(pdu->tag, pdu->id, v9stat.mode,

                           v9stat.atime, v9stat.mtime, v9stat.length);



    complete_pdu(s, pdu, err);

}

