int av_reduce(int *dst_nom, int *dst_den, int64_t nom, int64_t den, int64_t max){

    AVRational a0={0,1}, a1={1,0};

    int sign= (nom<0) ^ (den<0);

    int64_t gcd= ff_gcd(FFABS(nom), FFABS(den));



    nom = FFABS(nom)/gcd;

    den = FFABS(den)/gcd;

    if(nom<=max && den<=max){

        a1= (AVRational){nom, den};

        den=0;

    }



    while(den){

        int64_t x       = nom / den;

        int64_t next_den= nom - den*x;

        int64_t a2n= x*a1.num + a0.num;

        int64_t a2d= x*a1.den + a0.den;



        if(a2n > max || a2d > max){

            if(a1.num) x= (max - a0.num) / a1.num;

            if(a1.den) x= FFMIN(x, (max - a0.den) / a1.den);



            // Won't overflow, sum == original denominator

            if (den*(2*x*a1.den + a0.den) > nom*a1.den)

                a1 = (AVRational){x*a1.num + a0.num, x*a1.den + a0.den};

            break;

        }



        a0= a1;

        a1= (AVRational){a2n, a2d};

        nom= den;

        den= next_den;

    }

    assert(ff_gcd(a1.num, a1.den) == 1);



    *dst_nom = sign ? -a1.num : a1.num;

    *dst_den = a1.den;



    return den==0;

}

static void process_subpacket_9 (QDM2Context *q, QDM2SubPNode *node)

{

    GetBitContext gb;

    int i, j, k, n, ch, run, level, diff;



    init_get_bits(&gb, node->packet->data, node->packet->size*8);



    n = coeff_per_sb_for_avg[q->coeff_per_sb_select][QDM2_SB_USED(q->sub_sampling) - 1] + 1; // same as averagesomething function



    for (i = 1; i < n; i++)

        for (ch=0; ch < q->nb_channels; ch++) {

            level = qdm2_get_vlc(&gb, &vlc_tab_level, 0, 2);

            q->quantized_coeffs[ch][i][0] = level;



            for (j = 0; j < (8 - 1); ) {

                run = qdm2_get_vlc(&gb, &vlc_tab_run, 0, 1) + 1;

                diff = qdm2_get_se_vlc(&vlc_tab_diff, &gb, 2);



                for (k = 1; k <= run; k++)

                    q->quantized_coeffs[ch][i][j + k] = (level + ((k*diff) / run));



                level += diff;

                j += run;

            }

        }



    for (ch = 0; ch < q->nb_channels; ch++)

        for (i = 0; i < 8; i++)

            q->quantized_coeffs[ch][0][i] = 0;

}

