static int vfio_add_capabilities(VFIOPCIDevice *vdev)

{

    PCIDevice *pdev = &vdev->pdev;

    int ret;



    if (!(pdev->config[PCI_STATUS] & PCI_STATUS_CAP_LIST) ||

        !pdev->config[PCI_CAPABILITY_LIST]) {

        return 0; /* Nothing to add */

    }



    ret = vfio_add_std_cap(vdev, pdev->config[PCI_CAPABILITY_LIST]);

    if (ret) {

        return ret;

    }



    /* on PCI bus, it doesn't make sense to expose extended capabilities. */

    if (!pci_is_express(pdev) ||

        !pci_bus_is_express(pdev->bus) ||

        !pci_get_long(pdev->config + PCI_CONFIG_SPACE_SIZE)) {

        return 0;

    }



    return vfio_add_ext_cap(vdev);

}

static void tcg_reg_alloc_start(TCGContext *s)

{

    int i;

    TCGTemp *ts;

    for(i = 0; i < s->nb_globals; i++) {

        ts = &s->temps[i];

        if (ts->fixed_reg) {

            ts->val_type = TEMP_VAL_REG;

        } else {

            ts->val_type = TEMP_VAL_MEM;

        }

    }

    for(i = s->nb_globals; i < s->nb_temps; i++) {

        ts = &s->temps[i];

        ts->val_type = TEMP_VAL_DEAD;

        ts->mem_allocated = 0;

        ts->fixed_reg = 0;

    }

    for(i = 0; i < TCG_TARGET_NB_REGS; i++) {

        s->reg_to_temp[i] = -1;

    }

}

static void format_string(StringOutputVisitor *sov, Range *r, bool next,

                          bool human)

{

    if (r->end - r->begin > 1) {

        if (human) {

            g_string_append_printf(sov->string, "0x%" PRIx64 "-0x%" PRIx64,

                                   r->begin, r->end - 1);



        } else {

            g_string_append_printf(sov->string, "%" PRId64 "-%" PRId64,

                                   r->begin, r->end - 1);

        }

    } else {

        if (human) {

            g_string_append_printf(sov->string, "0x%" PRIx64, r->begin);

        } else {

