static void display_picref(AVFilterBufferRef *picref, AVRational time_base)

{

    int x, y;

    uint8_t *p0, *p;

    int64_t delay;



    if (picref->pts != AV_NOPTS_VALUE) {

        if (last_pts != AV_NOPTS_VALUE) {

            /* sleep roughly the right amount of time;

             * usleep is in microseconds, just like AV_TIME_BASE. */

            delay = av_rescale_q(picref->pts - last_pts,

                                 time_base, AV_TIME_BASE_Q);

            if (delay > 0 && delay < 1000000)

                usleep(delay);

        }

        last_pts = picref->pts;

    }



    /* Trivial ASCII grayscale display. */

    p0 = picref->data[0];

    puts("\033c");

    for (y = 0; y < picref->video->h; y++) {

        p = p0;

        for (x = 0; x < picref->video->w; x++)

            putchar(" .-+#"[*(p++) / 52]);

        putchar('\n');

        p0 += picref->linesize[0];

    }

    fflush(stdout);

}

static int e1000_post_load(void *opaque, int version_id)

{

    E1000State *s = opaque;

    NetClientState *nc = qemu_get_queue(s->nic);



    if (!(s->compat_flags & E1000_FLAG_MIT)) {

        s->mac_reg[ITR] = s->mac_reg[RDTR] = s->mac_reg[RADV] =

            s->mac_reg[TADV] = 0;

        s->mit_irq_level = false;

    }

    s->mit_ide = 0;

    s->mit_timer_on = false;



    /* nc.link_down can't be migrated, so infer link_down according

     * to link status bit in mac_reg[STATUS].

     * Alternatively, restart link negotiation if it was in progress. */

    nc->link_down = (s->mac_reg[STATUS] & E1000_STATUS_LU) == 0;



    if (s->compat_flags & E1000_FLAG_AUTONEG &&

        s->phy_reg[PHY_CTRL] & MII_CR_AUTO_NEG_EN &&

        s->phy_reg[PHY_CTRL] & MII_CR_RESTART_AUTO_NEG &&

        !(s->phy_reg[PHY_STATUS] & MII_SR_AUTONEG_COMPLETE)) {

        nc->link_down = false;

        timer_mod(s->autoneg_timer, qemu_clock_get_ms(QEMU_CLOCK_VIRTUAL) + 500);

    }



    return 0;

}

static void set_sel_time(IPMIBmcSim *ibs,

                         uint8_t *cmd, unsigned int cmd_len,

                         uint8_t *rsp, unsigned int *rsp_len,

                         unsigned int max_rsp_len)

{

    uint32_t val;

    struct ipmi_time now;



    IPMI_CHECK_CMD_LEN(6);

    val = cmd[2] | (cmd[3] << 8) | (cmd[4] << 16) | (cmd[5] << 24);

    ipmi_gettime(&now);

    ibs->sel.time_offset = now.tv_sec - ((long) val);

}

static void hScale16To15_c(SwsContext *c, int16_t *dst, int dstW, const uint8_t *_src,

                           const int16_t *filter,

                           const int16_t *filterPos, int filterSize)

{

    int i;

    const uint16_t *src = (const uint16_t *) _src;

    int sh = av_pix_fmt_descriptors[c->srcFormat].comp[0].depth_minus1;



    for (i = 0; i < dstW; i++) {

        int j;

        int srcPos = filterPos[i];

        int val = 0;



        for (j = 0; j < filterSize; j++) {

            val += src[srcPos + j] * filter[filterSize * i + j];

        }

        // filter=14 bit, input=16 bit, output=30 bit, >> 15 makes 15 bit

        dst[i] = FFMIN(val >> sh, (1 << 15) - 1);

    }

}

