void SwScale_Init(){

    // generating tables:

    int i;

    for(i=0; i<768; i++){

	int c= MIN(MAX(i-256, 0), 255);

	clip_table[i]=c;

	yuvtab_2568[c]= clip_yuvtab_2568[i]=(0x2568*(c-16))+(256<<13);

	yuvtab_3343[c]= clip_yuvtab_3343[i]=0x3343*(c-128);

	yuvtab_0c92[c]= clip_yuvtab_0c92[i]=-0x0c92*(c-128);

	yuvtab_1a1e[c]= clip_yuvtab_1a1e[i]=-0x1a1e*(c-128);

	yuvtab_40cf[c]= clip_yuvtab_40cf[i]=0x40cf*(c-128);

    }



    for(i=0; i<768; i++)

    {

    	int v= clip_table[i];

	clip_table16b[i]= v>>3;

	clip_table16g[i]= (v<<3)&0x07E0;

	clip_table16r[i]= (v<<8)&0xF800;

	clip_table15b[i]= v>>3;

	clip_table15g[i]= (v<<2)&0x03E0;

	clip_table15r[i]= (v<<7)&0x7C00;

    }



}

void ff_framequeue_skip_samples(FFFrameQueue *fq, size_t samples, AVRational time_base)

{

    FFFrameBucket *b;

    size_t bytes;

    int planar, planes, i;



    check_consistency(fq);

    av_assert1(fq->queued);

    b = bucket(fq, 0);

    av_assert1(samples < b->frame->nb_samples);

    planar = av_sample_fmt_is_planar(b->frame->format);

    planes = planar ? b->frame->channels : 1;

    bytes = samples * av_get_bytes_per_sample(b->frame->format);

    if (!planar)

        bytes *= b->frame->channels;

    if (b->frame->pts != AV_NOPTS_VALUE)

        b->frame->pts += av_rescale_q(samples, av_make_q(1, b->frame->sample_rate), time_base);

    b->frame->nb_samples -= samples;

    b->frame->linesize[0] -= bytes;

    for (i = 0; i < planes; i++)

        b->frame->extended_data[i] += bytes;

    for (i = 0; i < planes && i < AV_NUM_DATA_POINTERS; i++)

        b->frame->data[i] = b->frame->extended_data[i];

    fq->total_samples_tail += samples;


    ff_framequeue_update_peeked(fq, 0);

}

