int coroutine_fn qemu_co_sendv(int sockfd, struct iovec *iov,

                               int len, int iov_offset)

{

    int total = 0;

    int ret;

    while (len) {

        ret = qemu_sendv(sockfd, iov, len, iov_offset + total);

        if (ret < 0) {

            if (errno == EAGAIN) {

                qemu_coroutine_yield();

                continue;

            }

            if (total == 0) {

                total = -1;

            }

            break;

        }

        total += ret, len -= ret;

    }



    return total;

}

static uint16_t nvme_set_feature(NvmeCtrl *n, NvmeCmd *cmd, NvmeRequest *req)

{

    uint32_t dw10 = le32_to_cpu(cmd->cdw10);

    uint32_t dw11 = le32_to_cpu(cmd->cdw11);



    switch (dw10) {

    case NVME_VOLATILE_WRITE_CACHE:

        blk_set_enable_write_cache(n->conf.blk, dw11 & 1);

        break;

    case NVME_NUMBER_OF_QUEUES:

        req->cqe.result =

            cpu_to_le32((n->num_queues - 1) | ((n->num_queues - 1) << 16));

        break;

    default:

        return NVME_INVALID_FIELD | NVME_DNR;

    }

    return NVME_SUCCESS;

}

yuv2gray16_X_c_template(SwsContext *c, const int16_t *lumFilter,

                        const int32_t **lumSrc, int lumFilterSize,

                        const int16_t *chrFilter, const int32_t **chrUSrc,

                        const int32_t **chrVSrc, int chrFilterSize,

                        const int32_t **alpSrc, uint16_t *dest, int dstW,

                        int y, enum PixelFormat target)

{

    int i;



    for (i = 0; i < (dstW >> 1); i++) {

        int j;

        int Y1 = 1 << 14;

        int Y2 = 1 << 14;



        for (j = 0; j < lumFilterSize; j++) {

            Y1 += lumSrc[j][i * 2]     * lumFilter[j];

            Y2 += lumSrc[j][i * 2 + 1] * lumFilter[j];

        }

        Y1 >>= 15;

        Y2 >>= 15;

        if ((Y1 | Y2) & 0x10000) {

            Y1 = av_clip_uint16(Y1);

            Y2 = av_clip_uint16(Y2);

        }

        output_pixel(&dest[i * 2 + 0], Y1);

        output_pixel(&dest[i * 2 + 1], Y2);

    }

}

