{

    struct capture_callback *cb;



    for (cb = cap->cb_head.lh_first; cb; cb = cb->entries.le_next) {

        if (cb->opaque == cb_opaque) {

            cb->ops.destroy (cb_opaque);

            QLIST_REMOVE (cb, entries);

            g_free (cb);



            if (!cap->cb_head.lh_first) {

