static int asf_read_generic_value(AVFormatContext *s, uint8_t *name, uint16_t name_len,

                                  int type, AVDictionary **met)

{

    AVIOContext *pb = s->pb;

    uint64_t value;

    char buf[32];



    switch (type) {

    case ASF_BOOL:

        value = avio_rl32(pb);

        break;

    case ASF_DWORD:

        value = avio_rl32(pb);

        break;

    case ASF_QWORD:

        value = avio_rl64(pb);

        break;

    case ASF_WORD:

        value = avio_rl16(pb);

        break;

    default:

        av_freep(&name);

        return AVERROR_INVALIDDATA;

    }

    snprintf(buf, sizeof(buf), "%"PRIu64, value);

    if (av_dict_set(met, name, buf, 0) < 0)

        av_log(s, AV_LOG_WARNING, "av_dict_set failed.\n");



    return 0;

}

static int check_jni_invocation(void *log_ctx)

{

    int ret = AVERROR_EXTERNAL;

    void *handle = NULL;

    void **jni_invocation = NULL;



    handle = dlopen(NULL, RTLD_LOCAL);

    if (!handle) {

        goto done;

    }



    jni_invocation = (void **)dlsym(handle, "_ZN13JniInvocation15jni_invocation_E");

    if (!jni_invocation) {

        av_log(log_ctx, AV_LOG_ERROR, "Could not find JniInvocation::jni_invocation_ symbol\n");

        goto done;

    }



    ret = !(jni_invocation != NULL && *jni_invocation != NULL);



done:

    if (handle) {

        dlclose(handle);

    }



    return ret;

}

static int SocketAddress_to_str(char *dest, int max_len,

                                const char *prefix, SocketAddress *addr,

                                bool is_listen, bool is_telnet)

{

    switch (addr->type) {

    case SOCKET_ADDRESS_KIND_INET:

        return snprintf(dest, max_len, "%s%s:%s:%s%s", prefix,

                        is_telnet ? "telnet" : "tcp", addr->u.inet->host,

                        addr->u.inet->port, is_listen ? ",server" : "");

        break;

    case SOCKET_ADDRESS_KIND_UNIX:

        return snprintf(dest, max_len, "%sunix:%s%s", prefix,

                        addr->u.q_unix->path, is_listen ? ",server" : "");

        break;

    case SOCKET_ADDRESS_KIND_FD:

        return snprintf(dest, max_len, "%sfd:%s%s", prefix, addr->u.fd->str,

                        is_listen ? ",server" : "");

        break;

    default:

        abort();

    }

}

