static bool vring_notify(VirtIODevice *vdev, VirtQueue *vq)

{

    uint16_t old, new;

    bool v;

    /* We need to expose used array entries before checking used event. */

    smp_mb();

    /* Always notify when queue is empty (when feature acknowledge) */

    if (virtio_has_feature(vdev, VIRTIO_F_NOTIFY_ON_EMPTY) &&

        !vq->inuse && vring_avail_idx(vq) == vq->last_avail_idx) {

        return true;

    }



    if (!virtio_has_feature(vdev, VIRTIO_RING_F_EVENT_IDX)) {

        return !(vring_avail_flags(vq) & VRING_AVAIL_F_NO_INTERRUPT);

    }



    v = vq->signalled_used_valid;

    vq->signalled_used_valid = true;

    old = vq->signalled_used;

    new = vq->signalled_used = vring_used_idx(vq);

    return !v || vring_need_event(vring_get_used_event(vq), new, old);

}

void thread_pool_free(ThreadPool *pool)

{

    if (!pool) {

        return;

    }



    assert(QLIST_EMPTY(&pool->head));



    qemu_mutex_lock(&pool->lock);



    /* Stop new threads from spawning */

    qemu_bh_delete(pool->new_thread_bh);

    pool->cur_threads -= pool->new_threads;

    pool->new_threads = 0;



    /* Wait for worker threads to terminate */

    pool->stopping = true;

    while (pool->cur_threads > 0) {

        qemu_sem_post(&pool->sem);

        qemu_cond_wait(&pool->worker_stopped, &pool->lock);

    }



    qemu_mutex_unlock(&pool->lock);



    qemu_bh_delete(pool->completion_bh);

    qemu_sem_destroy(&pool->sem);

    qemu_cond_destroy(&pool->worker_stopped);

    qemu_mutex_destroy(&pool->lock);

    g_free(pool);

}

static int virtio_blk_handle_rw_error(VirtIOBlockReq *req, int error,

    int is_read)

{

    BlockInterfaceErrorAction action =

        drive_get_on_error(req->dev->bs, is_read);

    VirtIOBlock *s = req->dev;



    if (action == BLOCK_ERR_IGNORE) {

        bdrv_mon_event(req->dev->bs, BDRV_ACTION_IGNORE, is_read);

        return 0;

    }



    if ((error == ENOSPC && action == BLOCK_ERR_STOP_ENOSPC)

            || action == BLOCK_ERR_STOP_ANY) {

        req->next = s->rq;

        s->rq = req;

        bdrv_mon_event(req->dev->bs, BDRV_ACTION_STOP, is_read);

        vm_stop(0);

    } else {

        virtio_blk_req_complete(req, VIRTIO_BLK_S_IOERR);

        bdrv_mon_event(req->dev->bs, BDRV_ACTION_REPORT, is_read);

    }



    return 1;

}

