{

    av_assert2(p < end);



    end-=2;

    p++;

    if(s->resync_marker){

        for(;p<end; p+=2){

            if(!*p){

                if     (!p[-1] && p[1]) return p - 1;

                else if(!p[ 1] && p[2]) return p;

