static inline int vmsvga_fifo_length(struct vmsvga_state_s *s)

{

    int num;



    if (!s->config || !s->enable) {

        return 0;

    }



    /* Check range and alignment.  */

    if ((CMD(min) | CMD(max) | CMD(next_cmd) | CMD(stop)) & 3) {

        return 0;

    }

    if (CMD(min) < (uint8_t *) s->cmd->fifo - (uint8_t *) s->fifo) {

        return 0;

    }

    if (CMD(max) > SVGA_FIFO_SIZE ||

        CMD(min) >= SVGA_FIFO_SIZE ||

        CMD(stop) >= SVGA_FIFO_SIZE ||

        CMD(next_cmd) >= SVGA_FIFO_SIZE) {

        return 0;

    }

    if (CMD(max) < CMD(min) + 10 * 1024) {

        return 0;

    }



    num = CMD(next_cmd) - CMD(stop);

    if (num < 0) {

        num += CMD(max) - CMD(min);

    }

    return num >> 2;

}

static void check_watchpoint(int offset, int len, int flags)

{

    CPUState *cpu = current_cpu;

    CPUArchState *env = cpu->env_ptr;

    target_ulong pc, cs_base;

    target_ulong vaddr;

    CPUWatchpoint *wp;

    int cpu_flags;



    if (cpu->watchpoint_hit) {

        /* We re-entered the check after replacing the TB. Now raise

         * the debug interrupt so that is will trigger after the

         * current instruction. */

        cpu_interrupt(cpu, CPU_INTERRUPT_DEBUG);

        return;

    }

    vaddr = (cpu->mem_io_vaddr & TARGET_PAGE_MASK) + offset;

    QTAILQ_FOREACH(wp, &cpu->watchpoints, entry) {

        if (cpu_watchpoint_address_matches(wp, vaddr, len)

            && (wp->flags & flags)) {

            wp->flags |= BP_WATCHPOINT_HIT;

            if (!cpu->watchpoint_hit) {

                cpu->watchpoint_hit = wp;

                tb_check_watchpoint(cpu);

                if (wp->flags & BP_STOP_BEFORE_ACCESS) {

                    cpu->exception_index = EXCP_DEBUG;

                    cpu_loop_exit(cpu);

                } else {

                    cpu_get_tb_cpu_state(env, &pc, &cs_base, &cpu_flags);

                    tb_gen_code(cpu, pc, cs_base, cpu_flags, 1);

                    cpu_resume_from_signal(cpu, NULL);

                }

            }

        } else {

            wp->flags &= ~BP_WATCHPOINT_HIT;

        }

    }

}

int qcrypto_pbkdf2(QCryptoHashAlgorithm hash,

                   const uint8_t *key, size_t nkey,

                   const uint8_t *salt, size_t nsalt,

                   unsigned int iterations,

                   uint8_t *out, size_t nout,

                   Error **errp)

{

    static const int hash_map[QCRYPTO_HASH_ALG__MAX] = {

        [QCRYPTO_HASH_ALG_MD5] = GCRY_MD_MD5,

        [QCRYPTO_HASH_ALG_SHA1] = GCRY_MD_SHA1,

        [QCRYPTO_HASH_ALG_SHA256] = GCRY_MD_SHA256,

    };

    int ret;



    if (hash >= G_N_ELEMENTS(hash_map) ||

        hash_map[hash] == GCRY_MD_NONE) {

        error_setg(errp, "Unexpected hash algorithm %d", hash);

        return -1;

    }



    ret = gcry_kdf_derive(key, nkey, GCRY_KDF_PBKDF2,

                          hash_map[hash],

                          salt, nsalt, iterations,

                          nout, out);

    if (ret != 0) {

        error_setg(errp, "Cannot derive password: %s",

                   gcry_strerror(ret));

        return -1;

    }



    return 0;

}

