void ppc_tb_set_jmp_target(uintptr_t jmp_addr, uintptr_t addr)

{

    tcg_insn_unit i1, i2;

    uint64_t pair;

    intptr_t diff = addr - jmp_addr;



    if (in_range_b(diff)) {

        i1 = B | (diff & 0x3fffffc);

        i2 = NOP;

    } else if (USE_REG_RA) {

        intptr_t lo, hi;

        diff = addr - (uintptr_t)tb_ret_addr;

        lo = (int16_t)diff;

        hi = (int32_t)(diff - lo);

        assert(diff == hi + lo);

        i1 = ADDIS | TAI(TCG_REG_TMP1, TCG_REG_RA, hi >> 16);

        i2 = ADDI | TAI(TCG_REG_TMP1, TCG_REG_TMP1, lo);

    } else {

        assert(TCG_TARGET_REG_BITS == 32 || addr == (int32_t)addr);

        i1 = ADDIS | TAI(TCG_REG_TMP1, 0, addr >> 16);

        i2 = ORI | SAI(TCG_REG_TMP1, TCG_REG_TMP1, addr);

    }

#ifdef HOST_WORDS_BIGENDIAN

    pair = (uint64_t)i1 << 32 | i2;

#else

    pair = (uint64_t)i2 << 32 | i1;

#endif



    /* ??? __atomic_store_8, presuming there's some way to do that

       for 32-bit, otherwise this is good enough for 64-bit.  */

    *(uint64_t *)jmp_addr = pair;

    flush_icache_range(jmp_addr, jmp_addr + 8);

}

const char *av_get_string(void *obj, const char *name, const AVOption **o_out, char *buf, int buf_len){

    const AVOption *o= av_find_opt(obj, name, NULL, 0, 0);

    void *dst;

    if(!o || o->offset<=0)

        return NULL;

    if(o->type != FF_OPT_TYPE_STRING && (!buf || !buf_len))

        return NULL;



    dst= ((uint8_t*)obj) + o->offset;

    if(o_out) *o_out= o;



    if(o->type == FF_OPT_TYPE_STRING)

        return dst;



    switch(o->type){

    case FF_OPT_TYPE_FLAGS:     snprintf(buf, buf_len, "0x%08X",*(int    *)dst);break;

    case FF_OPT_TYPE_INT:       snprintf(buf, buf_len, "%d" , *(int    *)dst);break;

    case FF_OPT_TYPE_INT64:     snprintf(buf, buf_len, "%"PRId64, *(int64_t*)dst);break;

    case FF_OPT_TYPE_FLOAT:     snprintf(buf, buf_len, "%f" , *(float  *)dst);break;

    case FF_OPT_TYPE_DOUBLE:    snprintf(buf, buf_len, "%f" , *(double *)dst);break;

    case FF_OPT_TYPE_RATIONAL:  snprintf(buf, buf_len, "%d/%d", ((AVRational*)dst)->num, ((AVRational*)dst)->den);break;

    default: return NULL;

    }

    return buf;

}

bool virtio_scsi_handle_cmd_vq(VirtIOSCSI *s, VirtQueue *vq)

{

    VirtIOSCSIReq *req, *next;

    int ret = 0;

    bool progress = false;



    QTAILQ_HEAD(, VirtIOSCSIReq) reqs = QTAILQ_HEAD_INITIALIZER(reqs);



    virtio_scsi_acquire(s);

    do {

        virtio_queue_set_notification(vq, 0);



        while ((req = virtio_scsi_pop_req(s, vq))) {

            progress = true;

            ret = virtio_scsi_handle_cmd_req_prepare(s, req);

            if (!ret) {

                QTAILQ_INSERT_TAIL(&reqs, req, next);

            } else if (ret == -EINVAL) {

                /* The device is broken and shouldn't process any request */

                while (!QTAILQ_EMPTY(&reqs)) {

                    req = QTAILQ_FIRST(&reqs);

                    QTAILQ_REMOVE(&reqs, req, next);

                    blk_io_unplug(req->sreq->dev->conf.blk);

                    scsi_req_unref(req->sreq);

                    virtqueue_detach_element(req->vq, &req->elem, 0);

                    virtio_scsi_free_req(req);

                }

