bool qpci_msix_masked(QPCIDevice *dev, uint16_t entry)

{

    uint8_t addr;

    uint16_t val;

    void *vector_addr = dev->msix_table + (entry * PCI_MSIX_ENTRY_SIZE);



    g_assert(dev->msix_enabled);

    addr = qpci_find_capability(dev, PCI_CAP_ID_MSIX);

