    features |= (1 << VIRTIO_NET_F_MAC);

    features |= (1 << VIRTIO_NET_F_GUEST_CSUM);

    features |= (1 << VIRTIO_NET_F_GUEST_TSO4);

    features |= (1 << VIRTIO_NET_F_GUEST_TSO6);

