        }

    }

    put_symbol(&s->c, s->header_state, s->spatial_decomposition_type, 0);

    put_symbol(&s->c, s->header_state, s->qlog, 1); 

    put_symbol(&s->c, s->header_state, s->mv_scale, 0); 

