        int i;



        for (i = 0; i < n_poll_fds; i++) {

            GPollFD *p = &poll_fds[i];



            if ((p->events & G_IO_IN) && FD_ISSET(p->fd, rfds)) {

                p->revents |= G_IO_IN;

            }

            if ((p->events & G_IO_OUT) && FD_ISSET(p->fd, wfds)) {

                p->revents |= G_IO_OUT;

            }

            if ((p->events & G_IO_ERR) && FD_ISSET(p->fd, xfds)) {

                p->revents |= G_IO_ERR;

            }

