static always_inline int dv_rl2vlc_size(int run, int l)

{

    int level = (l ^ (l >> 8)) - (l >> 8);

    int size;



    if (run < DV_VLC_MAP_RUN_SIZE && level < DV_VLC_MAP_LEV_SIZE) {

	size = dv_vlc_map[run][level].size; 

    }

    else { 

	size = (level < DV_VLC_MAP_LEV_SIZE) ? dv_vlc_map[0][level].size : 16;

	if (run) {

	    size += (run < 16) ? dv_vlc_map[run-1][0].size : 13;

	}

    }

    return size;

}

av_cold int ff_rdft_init(RDFTContext *s, int nbits, enum RDFTransformType trans)

{

    int n = 1 << nbits;

    int i;

    const double theta = (trans == RDFT || trans == IRIDFT ? -1 : 1)*2*M_PI/n;



    s->nbits           = nbits;

    s->inverse         = trans == IRDFT || trans == IRIDFT;

    s->sign_convention = trans == RIDFT || trans == IRIDFT ? 1 : -1;



    if (nbits < 4 || nbits > 16)

        return -1;



    if (ff_fft_init(&s->fft, nbits-1, trans == IRDFT || trans == RIDFT) < 0)

        return -1;



    s->tcos = ff_cos_tabs[nbits-4];

    s->tsin = ff_sin_tabs[nbits-4]+(trans == RDFT || trans == IRIDFT)*(n>>2);

    for (i = 0; i < (n>>2); i++) {

        s->tcos[i] = cos(i*theta);

        s->tsin[i] = sin(i*theta);

    }

    return 0;

}

static int io_channel_send_full(QIOChannel *ioc,

                                const void *buf, size_t len,

                                int *fds, size_t nfds)

{

    size_t offset = 0;



    while (offset < len) {

        ssize_t ret = 0;

        struct iovec iov = { .iov_base = (char *)buf + offset,

                             .iov_len = len - offset };



        ret = qio_channel_writev_full(

            ioc, &iov, 1,

            fds, nfds, NULL);

        if (ret == QIO_CHANNEL_ERR_BLOCK) {

            errno = EAGAIN;

            return -1;

        } else if (ret < 0) {

            if (offset) {

                return offset;

            }



            errno = EINVAL;

            return -1;

        }



        offset += ret;

    }



    return offset;

}

