static double get_volume(CompandContext *s, double in_lin)

{

    CompandSegment *cs;

    double in_log, out_log;

    int i;



    if (in_lin < s->in_min_lin)

        return s->out_min_lin;



    in_log = log(in_lin);



    for (i = 1;; i++)

        if (in_log <= s->segments[i + 1].x)

            break;



    cs = &s->segments[i];

    in_log -= cs->x;

    out_log = cs->y + in_log * (cs->a * in_log + cs->b);



    return exp(out_log);

}

static const uint8_t *pcx_rle_decode(const uint8_t *src, uint8_t *dst,

                            unsigned int bytes_per_scanline, int compressed) {

    unsigned int i = 0;

    unsigned char run, value;



    if (compressed) {

        while (i<bytes_per_scanline) {

            run = 1;

            value = *src++;

            if (value >= 0xc0) {

                run = value & 0x3f;

                value = *src++;

            }

            while (i<bytes_per_scanline && run--)

                dst[i++] = value;

        }

    } else {

        memcpy(dst, src, bytes_per_scanline);

        src += bytes_per_scanline;

    }



    return src;

}

