static int vc1t_read_header(AVFormatContext *s,

                           AVFormatParameters *ap)

{

    ByteIOContext *pb = s->pb;

    AVStream *st;

    int fps, frames;



    frames = get_le24(pb);

    if(get_byte(pb) != 0xC5 || get_le32(pb) != 4)

        return -1;



    /* init video codec */

    st = av_new_stream(s, 0);

    if (!st)

        return -1;



    st->codec->codec_type = CODEC_TYPE_VIDEO;

    st->codec->codec_id = CODEC_ID_WMV3;



    st->codec->extradata = av_malloc(VC1_EXTRADATA_SIZE);

    st->codec->extradata_size = VC1_EXTRADATA_SIZE;

    get_buffer(pb, st->codec->extradata, VC1_EXTRADATA_SIZE);

    st->codec->height = get_le32(pb);

    st->codec->width = get_le32(pb);

    if(get_le32(pb) != 0xC)

        return -1;

    url_fskip(pb, 8);

    fps = get_le32(pb);

    if(fps == -1)

        av_set_pts_info(st, 32, 1, 1000);

    else{

        av_set_pts_info(st, 24, 1, fps);

        st->duration = frames;

    }



    return 0;

}

static int pci_qdev_init(DeviceState *qdev, DeviceInfo *base)

{

    PCIDevice *pci_dev = (PCIDevice *)qdev;

    PCIDeviceInfo *info = container_of(base, PCIDeviceInfo, qdev);

    PCIBus *bus;

    int devfn, rc;



    /* initialize cap_present for pci_is_express() and pci_config_size() */

    if (info->is_express) {

        pci_dev->cap_present |= QEMU_PCI_CAP_EXPRESS;

    }



    bus = FROM_QBUS(PCIBus, qdev_get_parent_bus(qdev));

    devfn = pci_dev->devfn;

    pci_dev = do_pci_register_device(pci_dev, bus, base->name, devfn,

                                     info->config_read, info->config_write,

                                     info->header_type);

    assert(pci_dev);

    rc = info->init(pci_dev);

    if (rc != 0)

        return rc;

    if (qdev->hotplugged)

        bus->hotplug(pci_dev, 1);

    return 0;

}

