void qemu_opts_print(QemuOpts *opts, const char *separator)

{

    QemuOpt *opt;

    QemuOptDesc *desc = opts->list->desc;

    const char *sep = "";



    if (opts->id) {

        printf("id=%s", opts->id); /* passed id_wellformed -> no commas */

        sep = separator;

    }



    if (desc[0].name == NULL) {

        QTAILQ_FOREACH(opt, &opts->head, next) {

            printf("%s%s=", sep, opt->name);

            escaped_print(opt->str);

            sep = separator;

        }

        return;

    }

    for (; desc && desc->name; desc++) {

        const char *value;

        QemuOpt *opt = qemu_opt_find(opts, desc->name);



        value = opt ? opt->str : desc->def_value_str;

        if (!value) {

            continue;

        }

        if (desc->type == QEMU_OPT_STRING) {

            printf("%s%s=", sep, desc->name);

            escaped_print(value);

        } else if ((desc->type == QEMU_OPT_SIZE ||

                    desc->type == QEMU_OPT_NUMBER) && opt) {

            printf("%s%s=%" PRId64, sep, desc->name, opt->value.uint);

        } else {

            printf("%s%s=%s", sep, desc->name, value);

        }

        sep = separator;

    }

}

static inline void scale_mv(AVSContext *h, int *d_x, int *d_y,

                            cavs_vector *src, int distp)

{

    int den = h->scale_den[FFMAX(src->ref, 0)];



    *d_x = (src->x * distp * den + 256 + FF_SIGNBIT(src->x)) >> 9;

    *d_y = (src->y * distp * den + 256 + FF_SIGNBIT(src->y)) >> 9;

}

static void tcg_out_dat_rIN(TCGContext *s, int cond, int opc, int opneg,

                            TCGArg dst, TCGArg lhs, TCGArg rhs,

                            bool rhs_is_const)

{

    /* Emit either the reg,imm or reg,reg form of a data-processing insn.

     * rhs must satisfy the "rIN" constraint.

     */

    if (rhs_is_const) {

        int rot = encode_imm(rhs);

        if (rot < 0) {

            rhs = -rhs;

            rot = encode_imm(rhs);

            assert(rot >= 0);

            opc = opneg;

        }

        tcg_out_dat_imm(s, cond, opc, dst, lhs, rotl(rhs, rot) | (rot << 7));

    } else {

        tcg_out_dat_reg(s, cond, opc, dst, lhs, rhs, SHIFT_IMM_LSL(0));

    }

}

static void build_guest_fsinfo_for_virtual_device(char const *syspath,

                                                  GuestFilesystemInfo *fs,

                                                  Error **errp)

{

    DIR *dir;

    char *dirpath;

    struct dirent entry, *result;



    dirpath = g_strdup_printf("%s/slaves", syspath);

    dir = opendir(dirpath);

    if (!dir) {

        error_setg_errno(errp, errno, "opendir(\"%s\")", dirpath);

        g_free(dirpath);

        return;

    }

    g_free(dirpath);



    for (;;) {

        if (readdir_r(dir, &entry, &result) != 0) {

            error_setg_errno(errp, errno, "readdir_r(\"%s\")", dirpath);

            break;

        }

        if (!result) {

            break;

        }



        if (entry.d_type == DT_LNK) {

            g_debug(" slave device '%s'", entry.d_name);

            dirpath = g_strdup_printf("%s/slaves/%s", syspath, entry.d_name);

            build_guest_fsinfo_for_device(dirpath, fs, errp);

            g_free(dirpath);



            if (*errp) {

                break;

            }

        }

    }



    closedir(dir);

}

