static void filter_mb_edgech( H264Context *h, uint8_t *pix, int stride, int16_t bS[4], int qp ) {

    int i;

    const int index_a = qp + h->slice_alpha_c0_offset;

    const int alpha = (alpha_table+52)[index_a];

    const int beta  = (beta_table+52)[qp + h->slice_beta_offset];



    if( bS[0] < 4 ) {

        int8_t tc[4];

        for(i=0; i<4; i++)

            tc[i] = bS[i] ? (tc0_table+52)[index_a][bS[i] - 1] + 1 : 0;

        h->s.dsp.h264_v_loop_filter_chroma(pix, stride, alpha, beta, tc);

    } else {

        h->s.dsp.h264_v_loop_filter_chroma_intra(pix, stride, alpha, beta);

    }

}

static int xvid_strip_vol_header(AVCodecContext *avctx, AVPacket *pkt,

                                 unsigned int header_len,

                                 unsigned int frame_len)

{

    int vo_len = 0, i;



    for (i = 0; i < header_len - 3; i++) {

        if (pkt->data[i]     == 0x00 &&

            pkt->data[i + 1] == 0x00 &&

            pkt->data[i + 2] == 0x01 &&

            pkt->data[i + 3] == 0xB6) {

            vo_len = i;

            break;

        }

    }



    if (vo_len > 0) {

        /* We need to store the header, so extract it */

        if (!avctx->extradata) {

            avctx->extradata = av_malloc(vo_len);



            memcpy(avctx->extradata, pkt->data, vo_len);

            avctx->extradata_size = vo_len;

        }

        /* Less dangerous now, memmove properly copies the two

         * chunks of overlapping data */

        memmove(pkt->data, &pkt->data[vo_len], frame_len - vo_len);

        pkt->size = frame_len - vo_len;

    }

    return 0;

}

