{

    uint64_t ret = 0;

#ifdef CONFIG_SOFTFLOAT

    ret |= env->fp_status.float_exception_flags << 52;

    if (env->fp_status.float_exception_flags)

        ret |= 1ULL << 63;

    env->ipr[IPR_EXC_SUM] &= ~0x3E:

