    cpu_check_irqs(env);

#endif

    env->psrs = (val & PSR_S)? 1 : 0;

    env->psrps = (val & PSR_PS)? 1 : 0;

#if !defined (TARGET_SPARC64)

    env->psret = (val & PSR_ET)? 1 : 0;

#endif

    set_cwp(val & PSR_CWP);

    env->cc_op = CC_OP_FLAGS;

}

