int opt_loglevel(void *optctx, const char *opt, const char *arg)

{

    const struct { const char *name; int level; } log_levels[] = {

        { "quiet"  , AV_LOG_QUIET   },

        { "panic"  , AV_LOG_PANIC   },

        { "fatal"  , AV_LOG_FATAL   },

        { "error"  , AV_LOG_ERROR   },

        { "warning", AV_LOG_WARNING },

        { "info"   , AV_LOG_INFO    },

        { "verbose", AV_LOG_VERBOSE },

        { "debug"  , AV_LOG_DEBUG   },

    };

    char *tail;

    int level;

    int i;



    for (i = 0; i < FF_ARRAY_ELEMS(log_levels); i++) {

        if (!strcmp(log_levels[i].name, arg)) {

            av_log_set_level(log_levels[i].level);

            return 0;

        }

    }



    level = strtol(arg, &tail, 10);

    if (*tail) {

        av_log(NULL, AV_LOG_FATAL, "Invalid loglevel \"%s\". "

               "Possible levels are numbers or:\n", arg);

        for (i = 0; i < FF_ARRAY_ELEMS(log_levels); i++)

            av_log(NULL, AV_LOG_FATAL, "\"%s\"\n", log_levels[i].name);

        exit(1);

    }

    av_log_set_level(level);

    return 0;

}

static void await_reference_mb_row(const H264Context *const h, H264Picture *ref,

                                   int mb_y)

{

    int ref_field         = ref->reference - 1;

    int ref_field_picture = ref->field_picture;

    int ref_height        = 16 * h->mb_height >> ref_field_picture;



    if (!HAVE_THREADS || !(h->avctx->active_thread_type & FF_THREAD_FRAME))

        return;



    /* FIXME: It can be safe to access mb stuff

     * even if pixels aren't deblocked yet. */



    ff_thread_await_progress(&ref->tf,

                             FFMIN(16 * mb_y >> ref_field_picture,

                                   ref_height - 1),

                             ref_field_picture && ref_field);

}

static int decode_cabac_mb_cbp_chroma( H264Context *h) {

    int ctx;

    int cbp_a, cbp_b;



    cbp_a = (h->left_cbp>>4)&0x03;

    cbp_b = (h-> top_cbp>>4)&0x03;



    ctx = 0;

    if( cbp_a > 0 ) ctx++;

    if( cbp_b > 0 ) ctx += 2;

    if( get_cabac( &h->cabac, &h->cabac_state[77 + ctx] ) == 0 )

        return 0;



    ctx = 4;

    if( cbp_a == 2 ) ctx++;

    if( cbp_b == 2 ) ctx += 2;

    return 1 + get_cabac( &h->cabac, &h->cabac_state[77 + ctx] );

}

static BlockBackend *img_open_opts(const char *optstr,

                                   QemuOpts *opts, int flags, bool writethrough,

                                   bool quiet, bool force_share)

{

    QDict *options;

    Error *local_err = NULL;

    BlockBackend *blk;

    options = qemu_opts_to_qdict(opts, NULL);

    if (force_share) {

        if (qdict_haskey(options, BDRV_OPT_FORCE_SHARE)

            && !qdict_get_bool(options, BDRV_OPT_FORCE_SHARE)) {

            error_report("--force-share/-U conflicts with image options");


            return NULL;

        }

        qdict_put(options, BDRV_OPT_FORCE_SHARE, qbool_from_bool(true));

    }

    blk = blk_new_open(NULL, NULL, options, flags, &local_err);

    if (!blk) {

        error_reportf_err(local_err, "Could not open '%s': ", optstr);

        return NULL;

