void smbios_add_field(int type, int offset, const void *data, size_t len)

{

    struct smbios_field *field;



    smbios_check_collision(type, SMBIOS_FIELD_ENTRY);



    if (!smbios_entries) {

        smbios_entries_len = sizeof(uint16_t);

        smbios_entries = g_malloc0(smbios_entries_len);

    }

    smbios_entries = g_realloc(smbios_entries, smbios_entries_len +

                                                  sizeof(*field) + len);

    field = (struct smbios_field *)(smbios_entries + smbios_entries_len);

    field->header.type = SMBIOS_FIELD_ENTRY;

    field->header.length = cpu_to_le16(sizeof(*field) + len);



    field->type = type;

    field->offset = cpu_to_le16(offset);

    memcpy(field->data, data, len);



    smbios_entries_len += sizeof(*field) + len;

    (*(uint16_t *)smbios_entries) =

            cpu_to_le16(le16_to_cpu(*(uint16_t *)smbios_entries) + 1);

}

static int copy_parameter_set(void **to, void **from, int count, int size)

{

    int i;



    for (i = 0; i < count; i++) {

        if (to[i] && !from[i]) {

            av_freep(&to[i]);

        } else if (from[i] && !to[i]) {

            to[i] = av_malloc(size);

            if (!to[i])

                return AVERROR(ENOMEM);

        }



        if (from[i])

            memcpy(to[i], from[i], size);

    }



    return 0;

}

uint64_t helper_fadd(CPUPPCState *env, uint64_t arg1, uint64_t arg2)

{

    CPU_DoubleU farg1, farg2;



    farg1.ll = arg1;

    farg2.ll = arg2;



    if (unlikely(float64_is_infinity(farg1.d) && float64_is_infinity(farg2.d) &&

                 float64_is_neg(farg1.d) != float64_is_neg(farg2.d))) {

        /* Magnitude subtraction of infinities */

        farg1.ll = fload_invalid_op_excp(env, POWERPC_EXCP_FP_VXISI);

    } else {

        if (unlikely(float64_is_signaling_nan(farg1.d) ||

                     float64_is_signaling_nan(farg2.d))) {

            /* sNaN addition */

            fload_invalid_op_excp(env, POWERPC_EXCP_FP_VXSNAN);

        }

        farg1.d = float64_add(farg1.d, farg2.d, &env->fp_status);

    }



    return farg1.ll;

}

static void *clone_func(void *arg)

{

    new_thread_info *info = arg;

    CPUArchState *env;

    CPUState *cpu;

    TaskState *ts;



    rcu_register_thread();

    env = info->env;

    cpu = ENV_GET_CPU(env);

    thread_cpu = cpu;

    ts = (TaskState *)cpu->opaque;

    info->tid = gettid();

    cpu->host_tid = info->tid;

    task_settid(ts);

    if (info->child_tidptr)

        put_user_u32(info->tid, info->child_tidptr);

    if (info->parent_tidptr)

        put_user_u32(info->tid, info->parent_tidptr);

    /* Enable signals.  */

    sigprocmask(SIG_SETMASK, &info->sigmask, NULL);

    /* Signal to the parent that we're ready.  */

    pthread_mutex_lock(&info->mutex);

    pthread_cond_broadcast(&info->cond);

    pthread_mutex_unlock(&info->mutex);

    /* Wait until the parent has finshed initializing the tls state.  */

    pthread_mutex_lock(&clone_lock);

    pthread_mutex_unlock(&clone_lock);

    cpu_loop(env);

    /* never exits */

    return NULL;

}

void arm_cpu_do_unaligned_access(CPUState *cs, vaddr vaddr, int is_write,

                                 int is_user, uintptr_t retaddr)

{

    ARMCPU *cpu = ARM_CPU(cs);

    CPUARMState *env = &cpu->env;

    int target_el;

    bool same_el;



    if (retaddr) {

        /* now we have a real cpu fault */

        cpu_restore_state(cs, retaddr);

    }



    target_el = exception_target_el(env);

    same_el = (arm_current_el(env) == target_el);



    env->exception.vaddress = vaddr;



    /* the DFSR for an alignment fault depends on whether we're using

     * the LPAE long descriptor format, or the short descriptor format

     */

    if (arm_regime_using_lpae_format(env, cpu_mmu_index(env, false))) {

        env->exception.fsr = 0x21;

    } else {

        env->exception.fsr = 0x1;

    }



    if (is_write == 1 && arm_feature(env, ARM_FEATURE_V6)) {

        env->exception.fsr |= (1 << 11);

    }



    raise_exception(env, EXCP_DATA_ABORT,

                    syn_data_abort(same_el, 0, 0, 0, is_write == 1, 0x21),

                    target_el);

}

